import{c as a,Q as s,j as t,m as o}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"Harness Handbook: Making Evolving Agent Harnesses Readable, Navigable, and Editable","description":"","frontmatter":{"url":"https://arxiv.org/abs/2607.13285","title":"Harness Handbook: Making Evolving Agent Harnesses Readable, Navigable, and Editable","archived_date":"2026-07-26T00:00:00.000Z","arxiv_id":2607.13285,"authors":["Ruhan Wang","Yucheng Shi","Zongxia Li","Zhongzhi Li","Yue Yu","Junyao Yang","Kishan Panaganti","Haitao Mi","Dongruo Zhou"],"pdf_path":"pdfs/2607.13285.pdf","published_date":"2026-07","source_routine":"routine-c","topic":"harness-handbook-dynamic-workflows-omarsar0"},"headers":[],"relativePath":"research/papers/2026-07-26-harness-handbook-2607-13285.md","filePath":"research/papers/2026-07-26-harness-handbook-2607-13285.md","lastUpdated":1785909234000}'),n={name:"research/papers/2026-07-26-harness-handbook-2607-13285.md"};function r(l,e,i,d,g,h){return s(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="harness-handbook-making-evolving-agent-harnesses-readable-navigable-and-editable" tabindex="-1">Harness Handbook: Making Evolving Agent Harnesses Readable, Navigable, and Editable <a class="header-anchor" href="#harness-handbook-making-evolving-agent-harnesses-readable-navigable-and-editable" aria-label="Permalink to &quot;Harness Handbook: Making Evolving Agent Harnesses Readable, Navigable, and Editable&quot;">​</a></h1><h2 id="摘要-核心貢獻" tabindex="-1">摘要 / 核心貢獻 <a class="header-anchor" href="#摘要-核心貢獻" aria-label="Permalink to &quot;摘要 / 核心貢獻&quot;">​</a></h2><p>本文處理 agent harness 演化的核心瓶頸：<strong>修改行為前，先找到該改哪裡</strong>。現代 harness「大型、緊耦合、行為分散」（large, tightly coupled, behaviorally distributed），開發者與 coding agent 都難以把「想要的行為」映射到具體程式碼位置——這一步失敗，後續 edit plan 再好也落錯地方。</p><p>作者提出 <strong>Harness Handbook</strong>：由 harness codebase 經<strong>靜態分析 + LLM 輔助結構化</strong>自動合成的<strong>行為中心表示</strong>（behavior-centric representation），每條行為都連回實作它的原始碼位置。與傳統以「檔案／函式」組織實作知識的方式相反，Handbook 以「harness 做什麼」組織，讓人與 agent 先定位行為、再導航到程式碼。</p><p>配套機制 <strong>Behavior-Guided Progressive Disclosure (BGPD)</strong>：引導 agent 從高層行為描述逐級下降到相關實作細節，並<strong>把候選位置對照當前原始碼驗證</strong>（不是靠記憶或猜測）。</p><h3 id="handbook-結構" tabindex="-1">Handbook 結構 <a class="header-anchor" href="#handbook-結構" aria-label="Permalink to &quot;Handbook 結構&quot;">​</a></h3><ul><li><strong>三層文件樹（D）</strong>：L1 系統總覽（lifecycle + 主要 stage）→ L2 各執行 stage 的元件總覽 → L3 source-backed 單元細節（依模式為 function 或 file）。</li><li><strong>State-Register View（Z）</strong>：記錄跨 stage 邊界的狀態關係。</li><li>底層構件：program graph（resolved call edges）、stage skeleton、cross-stage state register、對 repo 驗證過的 source locator。</li><li><strong>兩種 leaf 模式</strong>：function-as-leaf（自 seed skeleton 由上而下）／file-as-leaf（由下而上推論）——依 codebase 規模擇一。</li></ul><h3 id="評測設定" tabindex="-1">評測設定 <a class="header-anchor" href="#評測設定" aria-label="Permalink to &quot;評測設定&quot;">​</a></h3><p>兩個開源 harness，各 30 條 behavior-driven modification requests（相同行為意圖）：</p><table tabindex="0"><thead><tr><th>Harness</th><th>語言/型態</th><th>規模</th><th>Handbook 模式</th></tr></thead><tbody><tr><td>Terminus-2</td><td>Python terminal agent</td><td>6 源檔／103 內部函式／257 resolved call edges</td><td>function-as-leaf，20 stages、106 L3 entries</td></tr><tr><td>Codex</td><td>Rust coding agent monorepo</td><td>2,267 源檔／34,363 內部函式／159,960 resolved call edges</td><td>file-as-leaf，140 stages、2,267 L3 entries</td></tr></tbody></table><h3 id="量化結果" tabindex="-1">量化結果 <a class="header-anchor" href="#量化結果" aria-label="Permalink to &quot;量化結果&quot;">​</a></h3><p><strong>Planning win rate（Handbook-Assisted vs Baseline）</strong></p><ul><li>Codex：28.3% → <strong>38.3%</strong>（+10.0 pt）</li><li>Terminus-2：26.7% → <strong>45.6%</strong>（+18.9 pt）</li><li>跨 judge 一致性：Codex 每個 judge 皆 +10.0 pt；Terminus-2 +13.3~+26.7 pt</li></ul><p><strong>Planner token 用量（每 request）</strong></p><ul><li>Codex：0.102M → 0.089M（<strong>−12.7%</strong>）</li><li>Terminus-2：0.058M → 0.053M（<strong>−8.6%</strong>）</li><li>即「planning 品質上升」與「planner token 下降」同時達成，非以更多 context 換品質</li></ul><p><strong>Behavior localization F1（對 Opus 4.8 reference）</strong></p><ul><li>Codex file-level：46.6% → 61.8%（+15.2）；symbol-level：38.3% → 57.1%（+18.8）</li><li>Terminus-2 file-level：74.1% → 84.7%（+10.6）；symbol-level：64.8% → 77.1%（+12.3）</li><li>對 GPT-5.5 reference：Codex file-level 47.3% → 52.3%（+5.0）；Terminus-2 file-level 76.5% → 89.3%（+12.8）</li></ul><p><strong>完全定位失敗率（Wrong）</strong></p><ul><li>Codex file-level：37.0% → 14.8%（<strong>−22.2 pt</strong>）</li><li>Terminus-2 symbol-level：24.1% → 13.8%（−10.3 pt）</li></ul><p><strong>分類別增益</strong>：Query 修改 +16.3~+26.7 pt；Cross-file 能力 +16.3~+20.0 pt；<strong>Search-Hostile（搜尋不友善）請求 +20.0~+33.3 pt</strong>——增益最大處正是 grep/關鍵詞搜尋最無力處。分難度：easy +3.7~18.3、medium +13.3~26.7、hard +3.7~23.3。</p><h2 id="與-workspace-的關聯" tabindex="-1">與 workspace 的關聯 <a class="header-anchor" href="#與-workspace-的關聯" aria-label="Permalink to &quot;與 workspace 的關聯&quot;">​</a></h2><ul><li>本 workspace 的 <code>.claude/</code> harness（rules/skills/agents/hooks）正是論文所謂「evolving harness」：多次 Routine 提到「改行為時不確定該改 core.md 還是 refs/ 還是 skill」——即論文定義的 behavior localization 問題。</li><li>L1/L2/L3 三層 + progressive disclosure 與 <code>context-management.md</code> §Progressive Disclosure「三層下沉落點」構念同源，本論文提供外部量化佐證（token 降 8.6~12.7% 同時品質升 10~18.9 pt）。</li><li><strong>最強遷移點</strong>：Search-Hostile 類別增益最大（+20~33 pt）——對應 workspace 中「語義存在但無固定關鍵詞」的規則（如「不可逆操作等確認」散落 core.md/security-hygiene/hooks），grep 式導航最弱之處。</li></ul>',22)])])}const u=a(n,[["render",r]]);export{p as __pageData,u as default};
